-- Domicilios FleboReport. Aplicar después de la migración inicial.
alter table public.professionals add column if not exists user_id uuid references auth.users(id) on delete set null;
create unique index if not exists professionals_user_per_workspace on public.professionals(workspace_id,user_id) where user_id is not null;
create table if not exists public.home_visits(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,patient_id uuid,scheduled_at timestamptz not null,address text not null,latitude double precision,longitude double precision,patient_phone text,status text not null default 'pending_assignment' check(status in('pending_assignment','pending_acceptance','accepted','en_route','at_home','samples_taken','completed','rejected','cancelled','rescheduled','not_performed')),priority text not null default 'normal' check(priority in('low','normal','high','urgent')),notes text,cancellation_reason text,created_by uuid not null references auth.users(id),completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workspace_id,id),foreign key(workspace_id,patient_id) references public.patients(workspace_id,id) on delete restrict);
create index if not exists home_visits_schedule_idx on public.home_visits(workspace_id,scheduled_at,status);
create table if not exists public.home_visit_assignments(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,home_visit_id uuid not null,professional_id uuid,assigned_user_id uuid references auth.users(id) on delete set null,status text not null default 'invited' check(status in('invited','accepted','rejected','withdrawn')),assigned_at timestamptz not null default now(),responded_at timestamptz,response_note text,created_by uuid references auth.users(id),foreign key(workspace_id,home_visit_id) references public.home_visits(workspace_id,id) on delete cascade,foreign key(workspace_id,professional_id) references public.professionals(workspace_id,id) on delete restrict);
create unique index if not exists home_visit_one_active_assignment on public.home_visit_assignments(workspace_id,home_visit_id) where status in('invited','accepted');
create table if not exists public.home_visit_tests(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,home_visit_id uuid not null,service_id uuid,test_name text not null,vessel text,quantity integer not null default 1 check(quantity>0),status text not null default 'pending' check(status in('pending','collected','not_collected')),source text not null default 'original' check(source in('original','additional')),notes text,added_by uuid not null references auth.users(id),added_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(workspace_id,home_visit_id) references public.home_visits(workspace_id,id) on delete cascade,foreign key(workspace_id,service_id) references public.services(workspace_id,id) on delete restrict);
create table if not exists public.home_visit_events(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,home_visit_id uuid not null,event_type text not null,from_status text,to_status text,description text,actor_user_id uuid references auth.users(id),occurred_at timestamptz not null default now(),metadata jsonb not null default '{}'::jsonb,foreign key(workspace_id,home_visit_id) references public.home_visits(workspace_id,id) on delete cascade);
create table if not exists public.home_visit_notifications(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,home_visit_id uuid not null,recipient_user_id uuid references auth.users(id),channel text not null check(channel in('in_app','whatsapp')),template_name text,destination_masked text,status text not null default 'queued' check(status in('queued','sent','failed','read','cancelled')),provider_message_id text,error_code text,created_at timestamptz not null default now(),sent_at timestamptz,foreign key(workspace_id,home_visit_id) references public.home_visits(workspace_id,id) on delete cascade);
create index if not exists home_visit_tests_visit_idx on public.home_visit_tests(workspace_id,home_visit_id);
create index if not exists home_visit_events_visit_idx on public.home_visit_events(workspace_id,home_visit_id,occurred_at desc);
create index if not exists home_visit_notifications_visit_idx on public.home_visit_notifications(workspace_id,home_visit_id,created_at desc);
create or replace function public.touch_home_visit_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now(); return new; end $$;
create trigger home_visits_touch_updated_at before update on public.home_visits for each row execute function public.touch_home_visit_updated_at();
create trigger home_visit_tests_touch_updated_at before update on public.home_visit_tests for each row execute function public.touch_home_visit_updated_at();
alter table public.home_visits enable row level security;
alter table public.home_visit_assignments enable row level security;
alter table public.home_visit_tests enable row level security;
alter table public.home_visit_events enable row level security;
alter table public.home_visit_notifications enable row level security;
create policy home_visits_read_member on public.home_visits for select to authenticated using(public.is_workspace_member(workspace_id));
create policy home_visits_insert_staff on public.home_visits for insert to authenticated with check(public.has_workspace_role(workspace_id,array['admin','clinician','reception']));
create policy home_visits_update_staff_assignee on public.home_visits for update to authenticated using(public.has_workspace_role(workspace_id,array['admin','clinician','reception']) or exists(select 1 from public.home_visit_assignments a where a.workspace_id=home_visits.workspace_id and a.home_visit_id=home_visits.id and a.assigned_user_id=auth.uid() and a.status in('invited','accepted'))) with check(public.is_workspace_member(workspace_id));
create policy home_visit_assignments_read on public.home_visit_assignments for select to authenticated using(public.is_workspace_member(workspace_id));
create policy home_visit_assignments_insert_staff on public.home_visit_assignments for insert to authenticated with check(public.has_workspace_role(workspace_id,array['admin','clinician','reception']));
create policy home_visit_assignments_update_staff_self on public.home_visit_assignments for update to authenticated using(public.has_workspace_role(workspace_id,array['admin','clinician','reception']) or assigned_user_id=auth.uid()) with check(public.is_workspace_member(workspace_id));
create policy home_visit_tests_read on public.home_visit_tests for select to authenticated using(public.is_workspace_member(workspace_id));
create policy home_visit_tests_insert_staff on public.home_visit_tests for insert to authenticated with check(public.has_workspace_role(workspace_id,array['admin','clinician','reception','technician']));
create policy home_visit_tests_update_staff on public.home_visit_tests for update to authenticated using(public.has_workspace_role(workspace_id,array['admin','clinician','reception','technician'])) with check(public.is_workspace_member(workspace_id));
create policy home_visit_events_read on public.home_visit_events for select to authenticated using(public.is_workspace_member(workspace_id));
create policy home_visit_events_insert_member on public.home_visit_events for insert to authenticated with check(public.is_workspace_member(workspace_id));
create policy home_visit_notifications_read on public.home_visit_notifications for select to authenticated using(public.is_workspace_member(workspace_id));
create policy home_visit_notifications_insert_staff on public.home_visit_notifications for insert to authenticated with check(public.has_workspace_role(workspace_id,array['admin','clinician','reception']));
create or replace function public.reject_home_visit_event_mutation() returns trigger language plpgsql set search_path='' as $$ begin raise exception 'El historial de domicilios es inmutable'; end $$;
create trigger home_visit_events_immutable before update or delete on public.home_visit_events for each row execute function public.reject_home_visit_event_mutation();